import{_ as a,o as d,c as e,a2 as r}from"./chunks/framework.BqDA2HS7.js";const u=JSON.parse('{"title":"两种路由怎么选","description":"","frontmatter":{},"headers":[],"relativePath":"routing.md","filePath":"routing.md"}'),o={name:"routing.md"};function i(n,t,l,s,h,c){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="两种路由怎么选" tabindex="-1">两种路由怎么选 <a class="header-anchor" href="#两种路由怎么选" aria-label="Permalink to &quot;两种路由怎么选&quot;">​</a></h1><p>两个入口共享已适配的模型目录、价格依据和安全准入，但采用不同执行结构。</p><h2 id="入口比较" tabindex="-1">入口比较 <a class="header-anchor" href="#入口比较" aria-label="Permalink to &quot;入口比较&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>规划路由</th><th>自动路由</th></tr></thead><tbody><tr><td>关注点</td><td>每次模型调用使用谁、是否审核或接管</td><td>整任务 Direct 还是任务 DAG、节点如何分配</td></tr><tr><td>任务拆分</td><td>不创建 DAG</td><td>必要时由规划模型生成 DAG</td></tr><tr><td>执行循环</td><td>接入方 Agent 的原生循环</td><td>独立任务运行时，工具仍由宿主执行</td></tr><tr><td>用户设置</td><td>六种策略各自的执行器、Judge 和参数</td><td>执行模型池、规划、拆分、最终审核与预算</td></tr><tr><td>DSH 主要展示</td><td>路由轨迹中的调用流程</td><td>任务 DAG 和自动路由记录</td></tr><tr><td>标准 Base URL</td><td>六个 <code>refract/*</code> 虚拟模型</td><td>不通过标准模型 API 隐式进入 DAG</td></tr><tr><td>当前定位</td><td>文本与原生工具的模型路由</td><td>DAG 拆分与收益探索的独立入口</td></tr></tbody></table><h2 id="建议的选择顺序" tabindex="-1">建议的选择顺序 <a class="header-anchor" href="#建议的选择顺序" aria-label="Permalink to &quot;建议的选择顺序&quot;">​</a></h2><p>日常任务先从规划 Static 开始。固定模型可用后，再根据需要选择 Stage、Task、Advisor、 Escalation 或 Composite。需要验证独立子问题与并行调用时，单独选择自动路由。</p><p>自动路由选择 Direct 时，它仍属于自动路由运行记录；不是自动变成某个规划策略。 Advisor 的最终回复 Gate 与自动路由的最终 Judge 也不是同一个策略配置。</p><h2 id="三类判断不要混淆" tabindex="-1">三类判断不要混淆 <a class="header-anchor" href="#三类判断不要混淆" aria-label="Permalink to &quot;三类判断不要混淆&quot;">​</a></h2><ol><li><strong>能否拆分</strong>：有没有独立子问题、依赖是否允许分开处理。</li><li><strong>是否选 DAG</strong>：准入、质量依据、规划与汇总开销、费用及时间预测是否支持它。</li><li><strong>候选能否交付</strong>：实际输出、工具证据和审核结果是否满足任务合同。</li></ol><p>Jev 可以为其中适合有限回答的问题提供信号，Python 执行最终规则。 “可以拆分”不等于“DAG 更便宜”，审核通过也不反向证明当初选路最优。</p><h2 id="共同边界" tabindex="-1">共同边界 <a class="header-anchor" href="#共同边界" aria-label="Permalink to &quot;共同边界&quot;">​</a></h2><p>Router 不承担技能组织、智能体驾驭工程、工具权限、上下文压缩或子 Agent 任务管理。 DSH 与 Codex 的接入合同不同，不能因为模型 API 返回成功就宣称其全部功能兼容。 本轮产品范围以 DSH 与 Codex CLI 为主；其他客户端的历史实验不扩大当前承诺。</p>',12)])])}const _=a(o,[["render",i]]);export{u as __pageData,_ as default};
